from functools import cmp_to_key

def concat_order(a, b):
    if a + b > b + a:
        return -1          # a first
    if a + b < b + a:
        return 1           # b first
    return 0

parts = ['34', '9', '3', '30']
print(''.join(sorted(parts, key=cmp_to_key(concat_order))))  # 934330

