def rank_players(records):
    ordered = sorted(records, key=lambda r: (-r['score'], r['time'], r['name']))
    result = []
    previous = None
    for position, record in enumerate(ordered, start=1):
        group = (record['score'], record['time'])
        if group != previous:
            rank, previous = position, group
        result.append([rank, record['name']])
    return result

def newest_first(versions):
    def version_key(text):
        parts = [int(part) for part in text.split('.')]
        while parts and parts[-1] == 0:
            parts.pop()   # '2.0' and '2' are the same release
        return parts
    return sorted(versions, key=version_key, reverse=True)
